/// The failure a cancelled analysis ends with: the typed `Cancelled`, which the operation
/// manager reports as a cancellation whatever the message.
fn cancelled() -> anyhow::Error {
    crate::failure::for_long_operation(anyhow::Error::new(ImportCancelled))
}

impl LongOperation for AnalyzeScrivenerProjectUseCase {
    type Output = ScrivenerAnalysisDto;

    fn execute(
        &self,
        progress_callback: Box<dyn Fn(OperationProgress) + Send>,
        cancel_flag: Arc<AtomicBool>,
    ) -> Result<Self::Output> {
        // The phase travels typed, for the interface to word (see `progress`).
        let report = |percent: f32, phase: &str| {
            progress_callback(OperationProgress::new(percent, Some(phase.to_string())));
        };

        report(0.0, "import.opening");
        let answers = scrivener::analysis_answers(&self.dto);
        // This computer's host name, to tell a lock left here from one left elsewhere:
        // compared, never kept.
        let options = scrivener_import::Options::default();
        report(5.0, "import.outline");
        let Some(analysis) = scrivener_import::analyze_cancellable(
            Path::new(&self.dto.source_path),
            &answers,
            &options,
            &cancel_flag,
        ) else {
            return Err(cancelled());
        };
        // Only a model the analysis itself built reaches here, and one always writes out:
        // a failure would be this crate's defect, reported with its chain as one.
        let dto =
            scrivener::analysis_to_dto(analysis).map_err(crate::failure::for_long_operation)?;
        if cancel_flag.load(Ordering::Relaxed) {
            return Err(cancelled());
        }

        // Notify listeners (parity with every other use case). Nothing about the project
        // rides the event: its path is the writer's, and nobody listening needs it.
        let uow = self.uow_factory.create();
        uow.publish_analyze_scrivener_project_event(Vec::new(), None);

        report(100.0, "import.done");
        Ok(dto)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::failure::{FailureReason, ProjectImportFailure};
    use crate::units_of_work::analyze_scrivener_project_uow::AnalyzeScrivenerProjectUnitOfWorkFactory;
    use common::database::db_context::DbContext;
    use common::event::EventHub;

    fn use_case(source: &Path) -> AnalyzeScrivenerProjectUseCase {
        let db = match DbContext::new() {
            Ok(db) => db,
            Err(e) => panic!("a store: {e}"),
        };
        let hub = Arc::new(EventHub::new());
        AnalyzeScrivenerProjectUseCase::new(
            Box::new(AnalyzeScrivenerProjectUnitOfWorkFactory::new(&db, &hub)),
            &AnalyzeScrivenerProjectDto {
                source_path: source.to_string_lossy().into_owned(),
                ..AnalyzeScrivenerProjectDto::default()
            },
        )
    }

    /// A cancelled analysis ends as the typed cancellation, having read nothing more.
    #[test]
    fn a_cancelled_analysis_ends_cancelled() {
        let dir = match tempfile::tempdir() {
            Ok(dir) => dir,
            Err(e) => panic!("a scratch folder: {e}"),
        };
        let spec = scrivener_fixtures::Spec::novel(
            scrivener_fixtures::Generation::Format20,
            scrivener_fixtures::Platform::Mac,
        );
        let folder = dir.path().join(spec.folder());
        if let Err(e) = spec.build().write_to(&folder) {
            panic!("writing the fixture: {e}");
        }
        let result = use_case(&folder).execute(Box::new(|_| {}), Arc::new(AtomicBool::new(true)));
        let Err(error) = result else {
            panic!("a cancelled analysis must not complete");
        };
        assert_eq!(
            ProjectImportFailure::from_any_message(&error.to_string()).reason,
            FailureReason::Cancelled
        );
    }
}
